solution.solution.py:
def leaderboard(players):
    return sorted(players, key=lambda p: (-p["score"], p["name"].lower()))


def sort_versions(versions):
    def parts(v):
        nums = [int(x) for x in v.split(".")]
        while len(nums) > 1 and nums[-1] == 0:
            nums.pop()
        return nums
    return sorted(versions, key=parts)


def longest_words(text, n):
    words = {w.lower() for w in text.split()}
    return sorted(words, key=lambda w: (-len(w), w))[:n]


def describe(command):
    match command.split():
        case ["go", direction]:
            return f"going {direction}"
        case ["take", *items] if items:
            return f"taking {', '.join(items)}"
        case ["quit" | "exit"]:
            return "bye"
        case _:
            return "unknown"

unitTests:
@test("leaderboard")
def _():
    players = [{"name": "bob", "score": 70}, {"name": "Ada", "score": 95}, {"name": "carol", "score": 95}, {"name": "Al", "score": 70}]
    check_eq([p["name"] for p in leaderboard(players)], ["Ada", "carol", "Al", "bob"])

@test("versions")
def _():
    check_eq(sort_versions(["1.10", "1.2", "1.9.1", "2.0", "1.9"]), ["1.2", "1.9", "1.9.1", "1.10", "2.0"])
    check_eq(sort_versions(["1.2.0", "1.2"]), ["1.2.0", "1.2"])

@test("longest words")
def _():
    check_eq(longest_words("the quick brown fox jumps over the lazy dog Quick", 3), ["brown", "jumps", "quick"])
    check_eq(longest_words("", 2), [])

@test("commands")
def _():
    check_eq(describe("go north"), "going north")
    check_eq(describe("take key lamp"), "taking key, lamp")
    check_eq(describe("exit"), "bye")
    check_eq(describe("take"), "unknown")
    check_eq(describe("go"), "unknown")
    check_eq(describe("dance wildly"), "unknown")

